// 2 - Normalize and Validate Into One Standard Record
// CRM field names are mapped here, once. Swapping CRMs means editing this map and the write-back.
const REQUIRED = ['event_id', 'deal.deal_id', 'deal.amount', 'deal.currency', 'company.name', 'contact.email'];
const get = (o, path) => path.split('.').reduce((v, k) => (v == null ? v : v[k]), o);
const blank = (v) => v === undefined || v === null || v === '';

return $input.all().map(({ json: e }) => {
  const record = {
    crm: e.crm || 'hubspot',
    event_id: String(e.event_id || ''),
    stage: e.property_value,
    occurred_at: e.occurred_at,
    deal: { ...e.deal, amount: Number(e.deal?.amount) },
    company: { ...e.company, name: (e.company?.name || '').trim() },
    contact: { ...e.contact, email: (e.contact?.email || '').trim().toLowerCase() },
  };
  const failed = REQUIRED.filter((p) => blank(get(record, p)));
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(record.contact.email)) failed.push('contact.email format');
  if (!(record.deal.amount > 0)) failed.push('deal.amount must be above 0');
  if (!/^[A-Z]{3}$/.test(record.deal.currency || '')) failed.push('deal.currency must be a 3 letter code');
  return {
    json: {
      ...record,
      validation: { passed: failed.length === 0, failed_fields: [...new Set(failed)], checked_at: new Date().toISOString() },
    },
  };
});

